                            shutil.move(file_path,fp2)
                            file_path=fp2
                        fileparam=file_path.replace(SRC,'')
                        html+="<tr><td><a href='../ViewSource/?file="+escape(fileparam)+"&md5="+MD5+"'>"+escape(fileparam)+"</a></td></tr>"
        context = {'title': 'Smali Source',
                    'files': html,
                    'md5': MD5,
                    }
        template="smali.html"
        return render(request,template,context)
    except:
        PrintException("[ERROR] Getting Smali Files")
        return HttpResponseRedirect('/error/')
def Find(request):
    try:
        m=re.match('^[0-9a-f]{32}$',request.POST['md5'])
        if m:
            MD5=request.POST['md5']
            q=request.POST['q']
            code=request.POST['code']
            matches=[]
            if code=='java':
                SRC=os.path.join(settings.UPLD_DIR, MD5+'/java_source/')
                ext='.java'
            elif code=='smali':
                SRC=os.path.join(settings.UPLD_DIR, MD5+'/smali_source/')
                ext='.smali'
            else:
                return HttpResponseRedirect('/error/')
            for dirName, subDir, files in os.walk(SRC):
                for jfile in files:
                    if jfile.endswith(ext):
                        file_path=os.path.join(SRC,dirName,jfile)
                        if "+" in jfile:
                            fp2=os.path.join(SRC,dirName,jfile.replace("+","x"))
                            shutil.move(file_path,fp2)
                            file_path=fp2
                        fileparam=file_path.replace(SRC,'')
                        with io.open(file_path,mode='r',encoding="utf8",errors="ignore") as f:
                            dat=f.read()
                        if q in dat:
                            matches.append("<a href='../ViewSource/?file="+escape(fileparam)+"&md5="+MD5+"&type=apk'>"+escape(fileparam)+"</a>")
        flz=len(matches)
        context = {'title': 'Search Results',
        'matches': matches,
        'term': q,
        'found' : str(flz),
        }
        template="search.html"
        return render(request,template,context)
    except:
        PrintException("[ERROR] Searching Failed")
        return HttpResponseRedirect('/error/')
def ManifestView(request):
    try:
        DIR=settings.BASE_DIR
        MD5=request.GET['md5']
        TYP=request.GET['type']
        BIN=request.GET['bin']
        m=re.match('^[0-9a-f]{32}$',MD5)
        if m and (TYP=='eclipse' or TYP=='studio' or TYP=='apk') and (BIN=='1' or BIN=='0'):
            APP_DIR=os.path.join(settings.UPLD_DIR, MD5+'/')
            TOOLS_DIR=os.path.join(DIR, 'StaticAnalyzer/tools/')
            if BIN=='1':
                x=True
            elif BIN=='0':
                x=False
            MANI=ReadManifest(APP_DIR,TOOLS_DIR,TYP,x)
            context = {'title': 'AndroidManifest.xml',
                        'file': 'AndroidManifest.xml',
                        'dat': MANI}
            template="view_mani.html"
            return render(request,template,context)
    except:
        PrintException("[ERROR] Viewing AndroidManifest.xml")
        return HttpResponseRedirect('/error/')
def ReadManifest(APP_DIR,TOOLS_DIR,TYP,BIN):
    try:
        dat=''
        if BIN==True:
            print "[INFO] Getting Manifest from Binary"
            print "[INFO] AXML -> XML"
            manifest=os.path.join(APP_DIR,"AndroidManifest.xml")
            if len(settings.AXMLPRINTER_BINARY) > 0 and isFileExists(settings.AXMLPRINTER_BINARY):
                CP_PATH = settings.AXMLPRINTER_BINARY
            else:
                CP_PATH = os.path.join(TOOLS_DIR,'AXMLPrinter2.jar')
            args=[settings.JAVA_PATH+'java','-jar', CP_PATH, manifest]
            dat=subprocess.check_output(args)
        else:
            print "[INFO] Getting Manifest from Source"
            if TYP=="eclipse":
                manifest=os.path.join(APP_DIR,"AndroidManifest.xml")
            elif TYP=="studio":
                manifest=os.path.join(APP_DIR,"app/src/main/AndroidManifest.xml")
            with io.open(manifest,mode='r',encoding="utf8",errors="ignore") as f:
                dat=f.read()
        return dat
    except:
        PrintException("[ERROR] Reading Manifest file")
def DynamicAnalyzer(request):
    print "\n[INFO] Dynamic Analysis Started"
    try:
        if request.method == 'POST':
            MD5=request.POST['md5']
            PKG=request.POST['pkg']
            LNCH=request.POST['lng']
            if re.findall(";|\$\(|\|\||&&",PKG) or re.findall(";|\$\(|\|\||&&",LNCH):
                print "[ATTACK] Possible RCE"
                return HttpResponseRedirect('/error/')
            m=re.match('^[0-9a-f]{32}$',MD5)
            if m:
                SCREEN_FILE=os.path.join(settings.SCREEN_DIR, 'screen.png')
                if os.path.exists(SCREEN_FILE):
                    os.remove(SCREEN_FILE)
                SCRDIR=os.path.join(settings.UPLD_DIR, MD5+'/screenshots-apk/')
                if os.path.isdir(SCRDIR):
                    shutil.rmtree(SCRDIR)
                Proxy("","","","")
                if settings.REAL_DEVICE:
                    print "\n[INFO] MobSF will perform Dynamic Analysis on real Android Device"
                else:
                    RefreshVM(settings.UUID,settings.SUUID,settings.VBOX)
                context = {'md5' : MD5,
                       'pkg' : PKG,
                       'lng' : LNCH,
                       'title': 'Start Testing',}
                template="start_test.html"
                return render(request,template,context)
            else:
                return HttpResponseRedirect('/error/')
        else:
            return HttpResponseRedirect('/error/')
    except:
        PrintException("[ERROR] DynamicAnalyzer")
        return HttpResponseRedirect('/error/')
def RefreshVM(uuid,snapshot_uuid,vbox_exe):
    print "\n[INFO] Refreshing MobSF VM"
    try:
        args=[vbox_exe,'controlvm',uuid,'poweroff']
        subprocess.call(args)
        print "\n[INFO] VM Closed"
        args=[vbox_exe,'snapshot',uuid,'restore',snapshot_uuid]
        subprocess.call(args)
        print "\n[INFO] VM Restore Snapshot"
        args=[vbox_exe,'startvm',uuid]
        subprocess.call(args)
        print "\n[INFO] VM Starting"
    except:
        PrintException("[ERROR] Refreshing MobSF VM")
